/// SAME RUN — R3b's "the cure must not perturb the path that never traps",
/// measured beside the trap it cured.
fn measure(
    atoms: &AtomTable,
    composition: &Composition,
    entries: &Entries,
    expect_cached: bool,
) -> Arm {
    let Entries {
        specimen,
        probe,
        happy_entry,
        happy_arg,
        error_arg,
    } = *entries;
